"""audit-ai-service — NFR module (generated by A2C CodeGenAgent).

Circuit breaking and retry budgets come from the E2A framework
(e2a_base.CircuitBreaker, e2a_base.RetryBudget); this module adds jittered
retry with backoff, the idempotency claim helper and graceful shutdown.
"""
import random
import signal
import time
from typing import Any, Callable, Dict, Optional, TypeVar

from e2a_base import BaseIdempotencyStore, CircuitBreaker, ClaimStatus, RetryBudget

T = TypeVar("T")
HEALTH_PATH = "/health"


class CircuitOpenError(RuntimeError):
    """The dependency's circuit breaker is open; fail fast."""


class DuplicateInFlightError(RuntimeError):
    """Another worker owns this idempotency key right now."""


def call_with_resilience(action: Callable[[], T], breaker: CircuitBreaker,
                         budget: Optional[RetryBudget] = None, retries: int = 3,
                         base_delay: float = 0.05) -> T:
    """Run `action` behind a circuit breaker with jittered exponential backoff
    retry. Retries are bounded by `retries` and by the shared retry budget."""
    budget = budget or RetryBudget()
    budget.deposit()
    attempt = 0
    while True:
        if not breaker.allow():
            raise CircuitOpenError("circuit open")
        try:
            result = action()
            breaker.record_success()
            return result
        except Exception:
            breaker.record_failure()
            attempt += 1
            if attempt > retries or not budget.withdraw():
                raise
            time.sleep(base_delay * (2 ** (attempt - 1)) * (0.5 + random.random()))


def run_idempotent(store: BaseIdempotencyStore, request_id: str, tenant_id: str,
                   action: Callable[[], Dict[str, Any]]) -> Dict[str, Any]:
    """Execute `action` at most once per (tenant, request_id): an atomic claim,
    then complete on success or fail (retryable) on error. A replay returns
    the stored result instead of executing again."""
    claim = store.claim(request_id, tenant_id=tenant_id)
    if claim.status == ClaimStatus.REPLAY:
        return dict(claim.result or {}, replayed=True)
    if claim.status != ClaimStatus.CLAIMED:
        raise DuplicateInFlightError(f"{request_id}: {claim.status.value}")
    try:
        result = action()
    except Exception:
        store.fail(request_id, retryable=True, tenant_id=tenant_id, owner=claim.owner)
        raise
    store.complete(request_id, result, tenant_id=tenant_id, owner=claim.owner)
    return result


def install_graceful_shutdown(on_shutdown: Callable[[], None]) -> None:
    """Run `on_shutdown` on SIGTERM (container stop) before exiting."""
    def _handler(signum: int, frame: Any) -> None:
        on_shutdown()
        raise SystemExit(0)
    signal.signal(signal.SIGTERM, _handler)
